def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if token.isascii() and token.isdigit():
            return int(token)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        if "" in parts:
            rejected.append(idx)
            continue

        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acct, amt_str = parts[1], parts[2]
            amt = parse_amount(amt_str)
            if amt is not None and acct not in balances:
                balances[acct] = amt
                history.append(("open", acct))
                continue
        elif verb == "deposit" and n_parts == 3:
            acct, amt_str = parts[1], parts[2]
            amt = parse_amount(amt_str)
            if amt is not None and amt > 0 and acct in balances:
                balances[acct] += amt
                history.append(("deposit", acct, amt))
                continue
        elif verb == "withdraw" and n_parts == 3:
            acct, amt_str = parts[1], parts[2]
            amt = parse_amount(amt_str)
            if (
                amt is not None
                and amt > 0
                and acct in balances
                and acct not in frozen
                and balances[acct] >= amt
            ):
                balances[acct] -= amt
                history.append(("withdraw", acct, amt))
                continue
        elif verb == "transfer" and n_parts == 4:
            src, dst, amt_str = parts[1], parts[2], parts[3]
            amt = parse_amount(amt_str)
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
                continue
        elif verb == "freeze" and n_parts == 2:
            acct = parts[1]
            if acct in balances and acct not in frozen:
                frozen.add(acct)
                history.append(("freeze", acct))
                continue
        elif verb == "unfreeze" and n_parts == 2:
            acct = parts[1]
            if acct in balances and acct in frozen:
                frozen.remove(acct)
                history.append(("unfreeze", acct))
                continue
        elif verb == "undo" and n_parts == 1:
            if history:
                entry = history.pop()
                kind = entry[0]
                if kind == "open":
                    del balances[entry[1]]
                elif kind == "deposit":
                    balances[entry[1]] -= entry[2]
                elif kind == "withdraw":
                    balances[entry[1]] += entry[2]
                elif kind == "transfer":
                    balances[entry[1]] += entry[3]
                    balances[entry[2]] -= entry[3]
                elif kind == "freeze":
                    frozen.remove(entry[1])
                elif kind == "unfreeze":
                    frozen.add(entry[1])
                continue

        rejected.append(idx)

    return balances, rejected
